"""
Verify all LCD codes in codim8_data.sobj.

For each entry codes[n] = S, check:
  - |S| = n, elements are distinct and in {1,...,255}
  - C_S is LCD (G G^T nonsingular)
  - S is a cap when n <= 72 or (n <= 120 and n even)
"""


# This file was *autogenerated* from the file codim8_verify.sage
from sage.all_cmdline import *   # import sage library

_sage_const_8 = Integer(8); _sage_const_2 = Integer(2); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_9 = Integer(9); _sage_const_73 = Integer(73); _sage_const_74 = Integer(74); _sage_const_121 = Integer(121); _sage_const_255 = Integer(255)
m = _sage_const_8 
F = GF(_sage_const_2 )

def is_lcd(H):
    """Check LCD: equivalent to (H H^T)^{-1} exists, i.e. U_S nonsingular."""
    return (H * H.transpose()).det() != _sage_const_0 

def is_cap(S):
    """S is a cap iff no a XOR b is in S for distinct a, b in S."""
    S_set = set(S)
    for i, a in enumerate(S):
        for b in S[i+_sage_const_1 :]:
            if (a ^ b) in S_set - {a, b}:
                return False
    return True

codes = load("codim8_data")
cap_ns = set(range(_sage_const_9 , _sage_const_73 )) | set(range(_sage_const_74 , _sage_const_121 , _sage_const_2 ))
errors = _sage_const_0 

for n in sorted(codes.keys()):
    S = codes[n]

    if len(S) != n or len(set(S)) != n or not all(_sage_const_1  <= x <= _sage_const_255  for x in S):
        print(f"FAIL n={n}: size or range error")
        errors += _sage_const_1 
        continue

    H = matrix(F, m, n, [[(s >> i) & _sage_const_1  for s in S] for i in range(m)])
    if not is_lcd(H):
        print(f"FAIL n={n}: not LCD")
        errors += _sage_const_1 
        continue

    if n in cap_ns and not is_cap(S):
        print(f"FAIL n={n}: not a cap")
        errors += _sage_const_1 
        continue

print(f"Verified {len(codes)} codes, {errors} errors.")

